// Skyward Sword HD story reader and map-mark condition (dev.31, sshd_story.h / sshd_dungeon.h):
// replays the native condition readbacks of the NPC map mark analysis's live snapshots (fixture
// generated by tools/skyward-sword-hd/gen_story_fixture.py)
// and checks the live pointer chain and the special-scene refusal over a fake guest.
#include <array>
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <iterator>
#include <map>
#include <string>
#include <vector>

#include "sshd_dungeon.h"
#include "sshd_story.h"

namespace {

struct FxMark {
    uint8_t f190[32];
    int room;
};
struct FxSnapshot {
    const char* name;
    const char* stage;
    int scene;
    const uint8_t* words; // 255 u16
    const uint8_t* scene_row;
    const uint8_t* temp;
    const uint8_t* zone; // rooms 0..15
    const FxMark* marks;
    int count;
};
#include "sshd_story_table.inc"
#include "sshd_story_fixture.inc"

sshd::StoryWords Words(const FxSnapshot& s) {
    sshd::StoryWords w;
    std::memcpy(w.w, s.words, sizeof(w.w));
    w.valid = true;
    return w;
}

bool Bit(const uint8_t* base, int n) {
    uint16_t w = 0;
    std::memcpy(&w, base + 2 * (n >> 4), 2);
    return ((w >> (n & 15)) & 1) != 0;
}

// SF(room, f) as main+0xB7F19C over the fixture's slot pieces
bool SceneFlag(const FxSnapshot& s, int room, int f, bool* v) {
    if (f >= 255 || f < 0) {
        *v = false;
        return true;
    }
    if (f >= 192) {
        if (room < 0 || room >= 16)
            return false;
        *v = Bit(s.zone, 64 * room + f - 192);
    } else if (f >= 128) {
        *v = Bit(s.temp, f - 128);
    } else {
        *v = Bit(s.scene_row, f);
    }
    return true;
}

void Table() {
    const sshd::StoryTable t = sshd::ParseStoryTable(kFxStoryTable);
    assert(t.valid);
    // reserved ids are not read
    assert(!t.Bits(0) && !t.Bits(2) && !t.Bits(-1) && !t.Bits(2048));
    const auto b = t.Bits(281);
    assert(b && b->word == 17 && b->shift == 3 && b->width == 1);
    // any anchor off: the table is not the decoded one
    uint8_t bad[sshd::kStoryTableBytes];
    std::memcpy(bad, kFxStoryTable, sizeof(bad));
    bad[2 * 400 + 1] ^= 0x10;
    assert(!sshd::ParseStoryTable(bad).valid);
    // multi-bit values: width from the low nibble
    sshd::StoryWords w;
    w.valid = true;
    uint8_t raw[sshd::kStoryTableBytes];
    std::memcpy(raw, kFxStoryTable, sizeof(raw));
    int multi = -1;
    for (int id = 1; id < sshd::kStoryIds && multi < 0; ++id)
        if (raw[2 * id] < 255 && (raw[2 * id + 1] & 15) == 6)
            multi = id;
    assert(multi > 0);
    const int word = raw[2 * multi], shift = raw[2 * multi + 1] >> 4;
    w.w[word] = static_cast<uint16_t>(0x7F << shift); // 7 bits set, width 7 keeps all
    assert(*sshd::StoryValue(t, w, multi) == 0x7F);
    w.valid = false;
    assert(!sshd::StoryValue(t, w, multi));
    // the dungeon clear ids and the Sky / plate ids sit where the module's old byte / bit table had
    // them (main+0x182E1F8 mirror layout: byte = 2 * word + shift / 8, bit = shift % 8)
    const int same[][3] = {{5, 0, 6},     {7, 1, 0},     {9, 1, 2},     {11, 1, 4},    {13, 1, 6},
                           {15, 2, 0},    {130, 0x0D, 0}, {281, 0x22, 3}, {282, 0x22, 4}, {283, 0x22, 5},
                           {284, 0x22, 6}, {285, 0x22, 7}, {286, 0x23, 0}, {379, 0x2C, 1}, {46, 0x0E, 7},
                           {47, 0x0F, 0}, {48, 0x0F, 1}};
    for (const auto& e : same) {
        const auto bb = t.Bits(e[0]);
        assert(bb && bb->width == 1 && 2 * bb->word + bb->shift / 8 == e[1] && bb->shift % 8 == e[2]);
    }
}

// Every native readback: the full condition over the fixture's flags equals the native +0x1A2.
void Readbacks() {
    const sshd::StoryTable t = sshd::ParseStoryTable(kFxStoryTable);
    int n = 0, story_terms = 0, scene_terms = 0, second = 0, toggles = 0;
    for (const auto& s : kFxSnapshots) {
        const sshd::StoryWords w = Words(s);
        for (int i = 0; i < s.count; ++i) {
            const FxMark& fm = s.marks[i];
            const sshd::MarkFields m = sshd::ParseMark(fm.f190);
            const auto sf = [&](int f, bool* v) { return SceneFlag(s, fm.room, f, v); };
            const auto story = [&](int id, uint32_t* v) {
                const auto r = sshd::StoryValue(t, w, id);
                if (r)
                    *v = *r;
                return r.has_value();
            };
            const bool c = sshd::MarkCondition(m, sf, story);
            if (c != (m.cached_final != 0)) {
                std::fprintf(stderr, "%s mark %d (type %u icon %u) reader %d native %d\n", s.name, i, m.type, m.icon, c,
                             m.cached_final);
                assert(false);
            }
            // the term counts (the native +0x1A0 / +0x1A1 caches are not the halves of every mark:
            // a settled type-0 mark can hold a stale scene cache, so only +0x1A2 is compared)
            if (m.stcond <= 1) {
                ++story_terms;
                uint32_t v = 0;
                assert(story(m.story, &v));
            }
            if (m.scond <= 1 && m.scene != 255) {
                ++scene_terms;
                bool v = false;
                assert(sf(m.scene, &v));
            }
            second += m.story2 >= 1 && m.story2 <= 254;
            toggles += m.toggle != 255;
            ++n;
        }
    }
    assert(n == kFxReadbacks && n == 201);
    // the replay covers story, scene and toggle terms and a second story
    assert(story_terms > 20 && scene_terms > 5 && toggles > 0 && second > 0);
    std::printf("story: %d native readbacks match (%d story, %d scene terms, %d toggles, %d second story)\n", n,
                story_terms, scene_terms, toggles, second);
}

// The fixture's facts: hero's four Sky portrait flags, owner / g0 Bamboo only; the Sky
// name flags 281..286 (hero 111111, owner 010110, g0 111100).
void Facts() {
    const sshd::StoryTable t = sshd::ParseStoryTable(kFxStoryTable);
    const auto get = [&](const char* name, int id) {
        for (const auto& s : kFxSnapshots)
            if (std::strcmp(s.name, name) == 0)
                return static_cast<int>(*sshd::StoryValue(t, Words(s), id));
        assert(false);
        return -1;
    };
    const char* hero = "hero-F020-native";
    const char* g0 = "g0-F020-native";
    const char* owner = "owner-restored";
    for (int id : {42, 150, 201, 400})
        assert(get(hero, id) == 1);
    assert(get(owner, 150) == 1 && get(owner, 42) == 0 && get(owner, 201) == 0 && get(owner, 400) == 0);
    assert(get(g0, 150) == 1 && get(g0, 42) == 0 && get(g0, 201) == 0 && get(g0, 400) == 0);
    const int hero_n[] = {1, 1, 1, 1, 1, 1}, owner_n[] = {0, 1, 0, 1, 1, 0}, g0_n[] = {1, 1, 1, 1, 0, 0};
    for (int i = 0; i < 6; ++i) {
        assert(get(hero, 281 + i) == hero_n[i]);
        assert(get(owner, 281 + i) == owner_n[i]);
        assert(get(g0, 281 + i) == g0_n[i]);
    }
    // Gortram's 274: hero only; Thunder Dragon 509 and Mogma 180: hero only
    assert(get("hero-F301_4-native", 274) == 1);
    assert(get(hero, 509) == 1 && get(owner, 509) == 0 && get(hero, 180) == 1 && get(owner, 180) == 0);
}

// The live chain over a fake guest: main+0x182E1F0 -> manager, +0x18 -> metadata, +8 -> table;
// main+0x2BF9CC0 -> save manager, +0x10 + 0x8E4 = words; the first group-1 object decides the
// special-scene alternate.
void Live() {
    constexpr uint64_t kMain = 0x80000000, kMgr = 0x90000000, kMeta = 0x90001000, kTable = 0x90002000,
                       kSave = 0x91000000;
    std::map<uint64_t, std::vector<uint8_t>> mem;
    const auto put = [&](uint64_t a, size_t n) -> std::vector<uint8_t>& {
        mem[a] = std::vector<uint8_t>(n, 0);
        return mem[a];
    };
    const auto u64 = [&](std::vector<uint8_t>& b, size_t off, uint64_t v) { std::memcpy(&b[off], &v, 8); };
    const auto rd = [&](uint64_t addr, void* out, size_t n) {
        for (const auto& [a, b] : mem)
            if (addr >= a && addr + n <= a + b.size()) {
                std::memcpy(out, b.data() + (addr - a), n);
                return true;
            }
        return false;
    };
    u64(put(kMain + sshd::kStoryMgrPtr, 8), 0, kMgr);
    u64(put(kMgr, 0x20), 0x18, kMeta);
    u64(put(kMeta, 0x10), 8, kTable);
    std::memcpy(put(kTable, sshd::kStoryTableBytes).data(), kFxStoryTable, sshd::kStoryTableBytes);
    assert(sshd::StoryTableAddr(rd, kMain) == kTable);
    auto& save = put(kSave, 0xD000);
    u64(put(kMain + sshd::kSaveMgrPtr, 8), 0, kSave);
    const FxSnapshot& hero = kFxSnapshots[10];
    std::memcpy(&save[0x10 + 0x8E4], hero.words, 2 * sshd::kStoryWords);
    save[0x53D0 + 0x8E4] = 0xEE; // the alternate buffer differs
    // tree: root node -> child node (object group 2) -> sibling node (object group 1, profile 0x2BB)
    auto& root = put(kMain + sshd::kObjTreeRoot, 8);
    u64(root, 0, 0x92000000);
    u64(put(0x92000000, 40), 8, 0x92000100);
    auto& c1 = put(0x92000100, 40);
    u64(c1, 0, 0x92000000), u64(c1, 24, 0x92000200), u64(c1, 32, 0x93000000);
    auto& c2 = put(0x92000200, 40);
    u64(c2, 0, 0x92000000), u64(c2, 32, 0x93001000);
    put(0x93000000, 0x18)[0x16] = 2;
    auto& scene = put(0x93001000, 0x18);
    scene[0x16] = 1;
    const uint16_t prof = 0x2BB;
    std::memcpy(&scene[0x10], &prof, 2);
    int why = -1, probed = 0;
    sshd::StoryWords w = sshd::StoryWordsOf(rd, kMain, &why, &probed);
    assert(w.valid && why == 0 && probed == 2);
    sshd::StoryTable t = sshd::ParseStoryTable(mem[kTable].data());
    assert(t.valid && *sshd::StoryValue(t, w, 400) == 1 && *sshd::StoryValue(t, w, 281) == 1);
    // a profile-0 scene with the manager's +0xCD06 set still uses the file in play
    std::memset(&scene[0x10], 0, 2);
    save[0xCD06] = 1;
    w = sshd::StoryWordsOf(rd, kMain, &why);
    assert(w.valid && why == 0);
    // ... and with +0xCD06 == 0 the native reads the alternate buffer: refused
    save[0xCD06] = 0;
    w = sshd::StoryWordsOf(rd, kMain, &why);
    assert(!w.valid && why == 2 && !sshd::StoryValue(t, w, 400));
    // no save manager
    std::memset(mem[kMain + sshd::kSaveMgrPtr].data(), 0, 8);
    w = sshd::StoryWordsOf(rd, kMain, &why);
    assert(!w.valid && why == 1);
    // a broken chain: no table
    std::memset(mem[kMeta].data() + 8, 0, 8);
    assert(sshd::StoryTableAddr(rd, kMain) == 0);
}

// dev.41: the depth-first step's ancestor climb is capped, so a parent chain that
// loops (a transient state of the live tree, read off the game thread) ends the walk instead of
// hanging the sample; a deep but finite chain still finds its sibling.
void TreeCycle() {
    std::map<uint64_t, std::array<uint64_t, 5>> nodes; // parent, child, -, sibling, object
    int reads = 0;
    const auto rd = [&](uint64_t addr, void* out, size_t n) {
        ++reads;
        for (const auto& [a, v] : nodes)
            if (addr >= a && addr + n <= a + sizeof(v)) {
                std::memcpy(out, reinterpret_cast<const uint8_t*>(v.data()) + (addr - a), n);
                return true;
            }
        return false;
    };
    // a self-parented leaf with no sibling, and a two-node parent loop
    nodes[0x1000] = {0x1000, 0, 0, 0, 0};
    uint64_t next = 1;
    assert(!sshd::NextTreeNode(rd, 0x1000, 0, &next) && next == 0);
    assert(reads <= 2 * sshd::kTreeClimbMax);
    nodes[0x2000] = {0x2100, 0, 0, 0, 0};
    nodes[0x2100] = {0x2000, 0, 0, 0, 0};
    reads = 0;
    assert(!sshd::NextTreeNode(rd, 0x2000, 0, &next) && next == 0);
    assert(reads <= 2 * sshd::kTreeClimbMax);
    // the first child, then a sibling found 40 levels up
    assert(sshd::NextTreeNode(rd, 0x2000, 0x5000, &next) && next == 0x5000);
    for (uint64_t i = 0; i < 40; ++i)
        nodes[0x10000 + 0x100 * i] = {i == 39 ? 0x30000 : 0x10000 + 0x100 * (i + 1), 0, 0, 0, 0};
    nodes[0x30000] = {0, 0, 0, 0x31000, 0};
    assert(sshd::NextTreeNode(rd, 0x10000, 0, &next) && next == 0x31000);
    // the end of a finite tree
    nodes[0x31000] = {0, 0, 0, 0, 0};
    assert(sshd::NextTreeNode(rd, 0x31000, 0, &next) && next == 0);
    // a chain longer than the cap ends the walk (fail closed)
    for (uint64_t i = 0; i < 70; ++i)
        nodes[0x40000 + 0x100 * i] = {i == 69 ? 0x30000 : 0x40000 + 0x100 * (i + 1), 0, 0, 0, 0};
    assert(!sshd::NextTreeNode(rd, 0x40000, 0, &next));

    // StoryWordsOf over a tree whose first leaf climbs into a parent loop before any group-1
    // object: it ends (reason 3, no words) instead of spinning
    constexpr uint64_t kMain = 0x80000000, kSave = 0x91000000;
    std::map<uint64_t, std::vector<uint8_t>> mem;
    const auto put = [&](uint64_t a, size_t n) -> std::vector<uint8_t>& {
        mem[a] = std::vector<uint8_t>(n, 0);
        return mem[a];
    };
    const auto u64 = [&](std::vector<uint8_t>& b, size_t off, uint64_t v) { std::memcpy(&b[off], &v, 8); };
    const auto rd2 = [&](uint64_t addr, void* out, size_t n) {
        ++reads;
        for (const auto& [a, b] : mem)
            if (addr >= a && addr + n <= a + b.size()) {
                std::memcpy(out, b.data() + (addr - a), n);
                return true;
            }
        return false;
    };
    put(kSave, 0xD000);
    u64(put(kMain + sshd::kSaveMgrPtr, 8), 0, kSave);
    u64(put(kMain + sshd::kObjTreeRoot, 8), 0, 0x92000000);
    auto& root = put(0x92000000, 40);
    u64(root, 0, 0x92000100), u64(root, 8, 0x92000100); // root's child is also its parent
    auto& leaf = put(0x92000100, 40);
    u64(leaf, 0, 0x92000000), u64(leaf, 32, 0x93000000); // the leaf's parent is the root: a loop
    put(0x93000000, 0x18)[0x16] = 2;                      // not the deciding group
    int why = -1;
    reads = 0;
    const sshd::StoryWords w = sshd::StoryWordsOf(rd2, kMain, &why);
    assert(!w.valid && why == 3 && reads < 4 * sshd::kTreeClimbMax + 16);

    // dev.42: a finite tree with no group-1 object reads the normal buffer (the native
    // getter's default); a tree still going at the kTreeWalkMax node cap is unknown: reason 3
    const auto chain = [&](int count) {
        for (auto it = mem.begin(); it != mem.end();)
            it = it->first >= 0xA0000000 ? mem.erase(it) : std::next(it);
        u64(mem[kMain + sshd::kObjTreeRoot], 0, 0xA0000000);
        for (int k = 0; k < count; ++k) {
            const uint64_t a = 0xA0000000 + 0x40ull * k;
            auto& nd = put(a, 40);
            u64(nd, 0, k == 0 ? 0 : a - 0x40);         // parent
            u64(nd, 8, k + 1 < count ? a + 0x40 : 0);  // first child; no sibling, no object
        }
    };
    const auto rd3 = [&](uint64_t addr, void* out, size_t n) { // the map is large here: look up
        auto it = mem.upper_bound(addr);
        if (it == mem.begin())
            return false;
        --it;
        if (addr + n > it->first + it->second.size())
            return false;
        std::memcpy(out, it->second.data() + (addr - it->first), n);
        return true;
    };
    int probed = 0;
    chain(40); // finite: its leaf climbs 39 parents to the end of the tree
    sshd::StoryWords w2 = sshd::StoryWordsOf(rd3, kMain, &why, &probed);
    assert(w2.valid && why == 0 && probed == 40);
    chain(sshd::kTreeWalkMax + 8);
    w2 = sshd::StoryWordsOf(rd3, kMain, &why, &probed);
    assert(!w2.valid && why == 3 && probed == sshd::kTreeWalkMax);
}

// The mark condition's second-story OR comes after the toggle, and fails closed only when the
// result depends on an unreadable value.
void Condition() {
    uint8_t mm[0x18]{};
    mm[4] = 255, mm[5] = 128, mm[6] = 0, mm[7] = 3; // scene 255 SET (false), toggle 128, story always
    const uint16_t s2 = 150;
    std::memcpy(mm + 0xA, &s2, 2);
    mm[0x14] = 1; // disable on toggle
    sshd::MarkFields m = sshd::ParseMark(mm);
    std::map<int, bool> flags{{128, true}};
    std::map<int, uint32_t> story{{150, 1}};
    bool story_ok = true;
    const auto sf = [&](int f, bool* v) {
        *v = flags[f];
        return true;
    };
    const auto st = [&](int id, uint32_t* v) {
        *v = story[id];
        return story_ok;
    };
    assert(sshd::MarkCondition(m, sf, st)); // suppressed, then the second story reveals it
    story[150] = 0;
    assert(!sshd::MarkCondition(m, sf, st));
    story_ok = false;
    assert(!sshd::MarkCondition(m, sf, st));
    // a true base never needs the second story
    m.scond = 3, m.toggle = 255;
    assert(sshd::MarkCondition(m, sf, st));
    // story modes 0 / 1 / 2
    story_ok = true;
    m.story2 = 255, m.stcond = 0, m.story = 42;
    story[42] = 2; // a counter: any non-zero
    assert(sshd::MarkCondition(m, sf, st));
    m.stcond = 1;
    assert(!sshd::MarkCondition(m, sf, st));
    m.stcond = 2, m.cached_story = 1;
    assert(sshd::MarkCondition(m, sf, st));
    m.stcond = 5;
    assert(!sshd::MarkCondition(m, sf, st));
}

} // namespace

int main() {
    Table();
    Readbacks();
    Facts();
    Live();
    TreeCycle();
    Condition();
    std::printf("sshd story: all checks passed\n");
    return 0;
}
